package com.havanduyet.quanlynhansu;
import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public class MainActivity extends Activity {
 private EmployeeDb db;private EditText search;private Spinner department,sort;private ListView list;private TextView stats,empty;private List<Employee> visible=new ArrayList<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);db=new EmployeeDb(this);search=findViewById(R.id.edtSearch);department=findViewById(R.id.spDepartment);sort=findViewById(R.id.spSort);list=findViewById(R.id.listEmployees);stats=findViewById(R.id.txtStatistics);empty=findViewById(R.id.txtEmpty);String[] deps={"Tất cả phòng ban","Hành chính","Phần mềm","Kỹ thuật","Dự án"};department.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,deps));sort.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Tên A → Z","Lương tăng dần","Lương giảm dần"}));AdapterView.OnItemSelectedListener refresh=new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int x,long id){reload();}public void onNothingSelected(AdapterView<?> p){}};department.setOnItemSelectedListener(refresh);sort.setOnItemSelectedListener(refresh);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){reload();}public void afterTextChanged(Editable e){}});findViewById(R.id.btnAdd).setOnClickListener(v->startActivity(new Intent(this,EmployeeFormActivity.class)));list.setOnItemClickListener((parent,v,pos,id)->{Intent i=new Intent(this,EmployeeDetailActivity.class);i.putExtra("code",visible.get(pos).code);startActivity(i);});}
 @Override protected void onResume(){super.onResume();reload();}
 private void reload(){if(db==null||department.getSelectedItem()==null||sort.getSelectedItem()==null)return;visible=db.search(search.getText().toString(),department.getSelectedItem().toString(),sort.getSelectedItem().toString());list.setAdapter(new EmployeeAdapter(this,visible));empty.setVisibility(visible.isEmpty()?View.VISIBLE:View.GONE);stats.setText("Tổng nhân sự: "+db.count()+"    •    Quỹ lương: "+NumberFormat.getNumberInstance(new Locale("vi","VN")).format(db.totalSalary())+" đ");}
}
